// ================================================================
// Code â€” Stamp Query Metadata onto Search Response â€” v7.0 FIXED
// 
// Uses $runIndex to match items (HTTP Request breaks paired item chain)
// ================================================================

// Get all search configs to match by index
let allConfigs = [];
try {
  allConfigs = $('Code â€” Build Axis-Specific Search Config').all();
} catch (e) {
  // Fallback: try to get from input
  allConfigs = [];
}

// Get run index to find the matching config
let runIndex = 0;
try {
  runIndex = $runIndex;
} catch (e) {
  try {
    runIndex = $itemIndex;
  } catch (e2) {
    runIndex = 0;
  }
}

// Get the matching search config
const searchInput = allConfigs[runIndex]?.json || {};

const label = searchInput.label || "";
const intent = searchInput.axis || "";
const q = searchInput.q || "";
const q_full = searchInput.q_full || "";
const duration_tier = searchInput.duration_tier || "";
const searchConfig = searchInput._searchConfig || {};

// Get items from current input (YouTube response, possibly already tagged)
const responseItems = $json.items || [];

const stamped = responseItems.map(v => ({
  ...v,
  query: { label, intent, q, q_full, duration_tier },
  // Ensure these are also at top level
  search_label: v.search_label || label,
  search_intent: v.search_intent || intent,
  search_q: v.search_q || q,
  search_q_full: v.search_q_full || q_full,
  duration_tier: v.duration_tier || duration_tier,
  _searchConfig: v._searchConfig || searchConfig
}));

return [{ json: { items: stamped } }];

// ================================================================
// Code â€” Batch IDs (Dedup) â€” v7.0
// 
// Extracts VIDEO IDs (not channel IDs) and creates batches
// Outputs batch_video_ids for API â€” Get Video Stats
// ================================================================

const rawInputs = $input.all();

const debugInfo = {
  inputCount: rawInputs.length,
  timestamp: new Date().toISOString()
};

// ================================================================
// EXTRACT VIDEOS FROM ALL INPUTS
// ================================================================
let allVideos = [];

for (const input of rawInputs) {
  const json = input.json || {};

  // Structure: { items: [...] } from Merge node
  if (Array.isArray(json.items)) {
    allVideos.push(...json.items);
  }
  // Structure: Direct video object
  else if (json.id?.videoId || json.snippet) {
    allVideos.push(json);
  }
}

debugInfo.videosExtracted = allVideos.length;

// ================================================================
// DEDUPLICATE BY VIDEO ID
// ================================================================
const seen = new Map();
const deduped = [];
const searchMetadataMap = {};

for (const video of allVideos) {
  // Extract VIDEO ID (not channel ID!)
  let videoId = null;

  if (video.id?.videoId) {
    // Standard YouTube Search API structure
    videoId = video.id.videoId;
  } else if (typeof video.id === 'string') {
    videoId = video.id;
  } else if (video.videoId) {
    videoId = video.videoId;
  }

  if (!videoId || seen.has(videoId)) {
    if (!videoId) debugInfo.skippedNoId = (debugInfo.skippedNoId || 0) + 1;
    continue;
  }

  seen.set(videoId, true);
  deduped.push({ ...video, _extractedVideoId: videoId });

  // Preserve search metadata
  searchMetadataMap[videoId] = {
    search_label: video.search_label || video._searchLabel || '',
    search_intent: video.search_intent || video._searchAxis || '',
    search_q: video.search_q || '',
    search_q_full: video.search_q_full || video._searchQuery || '',
    duration_tier: video.duration_tier || video._duration_tier || '',
    search_config: video._searchConfig || {}
  };
}

debugInfo.afterDedup = deduped.length;
debugInfo.duplicatesRemoved = allVideos.length - deduped.length;

// ================================================================
// MULTI-BATCH OUTPUT
// ================================================================
const MAX_TOTAL_VIDEOS = 250;
const BATCH_SIZE = 50;

const capped = deduped.slice(0, MAX_TOTAL_VIDEOS);

if (capped.length === 0) {
  return [{
    json: {
      batch_index: 0,
      batch_video_ids: '',
      video_count: 0,
      search_metadata_map: {},
      _error: 'No videos extracted',
      _debug: debugInfo
    }
  }];
}

const batches = [];
const totalBatches = Math.ceil(capped.length / BATCH_SIZE);

for (let i = 0; i < capped.length; i += BATCH_SIZE) {
  const batchVideos = capped.slice(i, i + BATCH_SIZE);
  const batchIndex = Math.floor(i / BATCH_SIZE);

  // Extract VIDEO IDs for this batch
  const batchIds = batchVideos
    .map(v => v._extractedVideoId)
    .filter(id => id && typeof id === 'string')
    .join(',');

  batches.push({
    json: {
      batch_index: batchIndex,
      batch_video_ids: batchIds,  // <-- THIS IS THE KEY FIELD
      video_count: batchVideos.length,
      search_metadata_map: searchMetadataMap,

      _batchMeta: {
        batch_number: batchIndex + 1,
        total_batches: totalBatches,
        videos_in_batch: batchVideos.length,
        is_last_batch: batchIndex === totalBatches - 1,
        sample_ids: batchIds.split(',').slice(0, 3)
      },

      _pipelineStats: {
        raw_input: allVideos.length,
        after_dedup: deduped.length,
        total_processing: capped.length
      },

      _debug: debugInfo
    }
  });
}

return batches;

// ================================================================
// Code â€” Extract Channel IDs (Dedup) â€” v7.0
// 
// Extracts unique channel IDs from merged video stats
// Works with new multi-batch structure from Code â€” Merge Batch Results
// ================================================================

const input = $input.first().json;

// Handle both old structure (direct items) and new structure (nested)
let items = [];

if (Array.isArray(input.items)) {
  items = input.items;
} else if (Array.isArray(input)) {
  items = input;
} else {
  // Try to find items in the input
  const allInputs = $input.all();
  for (const inp of allInputs) {
    if (Array.isArray(inp.json?.items)) {
      items.push(...inp.json.items);
    } else if (inp.json?.snippet?.channelId) {
      items.push(inp.json);
    }
  }
}

// Extract unique channel IDs
const channelIds = new Set();

for (const item of items) {
  const channelId = item.snippet?.channelId || item.channelId || item.channel_id;
  if (channelId && typeof channelId === 'string') {
    channelIds.add(channelId);
  }
}

const uniqueIds = Array.from(channelIds);

// Return empty-safe output
if (uniqueIds.length === 0) {
  return [{
    json: {
      channel_ids: '',
      _warning: 'No channel IDs found',
      _inputItemCount: items.length,
      _inputStructure: Object.keys(input || {})
    }
  }];
}

return [{
  json: {
    channel_ids: uniqueIds.join(','),
    _stats: {
      unique_channels: uniqueIds.length,
      videos_processed: items.length
    }
  }
}];

// ================================================================
// Code â€” Attach Channel Stats â€” v7.0 Multi-Batch Compatible
// 
// Enriches videos with channel statistics
// Preserves all search metadata including duration_tier
// ================================================================

const inputs = $input.all().map(i => i.json);

// Find the videos response (has contentDetails)
const videosJson = inputs.find(j =>
  Array.isArray(j.items) && j.items[0]?.snippet?.channelId && j.items[0]?.contentDetails
);

// Find the channels response (has subscriberCount)
const channelsJson = inputs.find(j =>
  Array.isArray(j.items) && j.items[0]?.id && j.items[0]?.statistics?.subscriberCount !== undefined
);

if (!videosJson) {
  return [{ json: { error: "Missing videos.list response", inputs_received: inputs.length } }];
}

// ================================================================
// GET SEARCH METADATA FROM MULTIPLE POSSIBLE SOURCES
// ================================================================
let searchMetadataMap = {};

// Try batch-related nodes
const possibleSources = [
  'Code â€” Batch IDs (Dedup)',
  'Code â€” Merge Batch Results'
];

for (const nodeName of possibleSources) {
  try {
    const nodeItems = $(nodeName).all();
    for (const item of nodeItems) {
      if (item.json?.search_metadata_map) {
        searchMetadataMap = { ...searchMetadataMap, ...item.json.search_metadata_map };
      }
    }
  } catch (e) { }
}

// Also check current inputs for metadata
for (const input of inputs) {
  if (input.search_metadata_map) {
    searchMetadataMap = { ...searchMetadataMap, ...input.search_metadata_map };
  }
}

// ================================================================
// BUILD CHANNEL STATS MAP
// ================================================================
const channelMap = new Map();
if (channelsJson) {
  for (const ch of channelsJson.items) {
    channelMap.set(ch.id, {
      subscriberCount: Number(ch.statistics?.subscriberCount || 0),
      viewCount: Number(ch.statistics?.viewCount || 0),
      videoCount: Number(ch.statistics?.videoCount || 0),
    });
  }
}

// ================================================================
// ENRICH VIDEOS
// ================================================================
const enriched = videosJson.items.map(v => {
  const cid = v.snippet?.channelId;
  const stats = channelMap.get(cid) || { subscriberCount: 0, viewCount: 0, videoCount: 0 };
  const searchMeta = searchMetadataMap[v.id] || {};

  return {
    ...v,
    channelStatistics: stats,

    // Search metadata
    search_label: searchMeta.search_label || "",
    search_intent: searchMeta.search_intent || "",
    search_q: searchMeta.search_q || "",
    search_q_full: searchMeta.search_q_full || "",
    duration_tier: searchMeta.duration_tier || "",
    _searchConfig: searchMeta.search_config || {}
  };
});

return [{ 
  json: { 
    items: enriched,
    _enrichmentStats: {
      videos_enriched: enriched.length,
      channels_found: channelMap.size,
      metadata_keys: Object.keys(searchMetadataMap).length
    }
  } 
}];

// ================================================================
// Set â€” Current Video Context â€” v7.0
// 
// Prepares video data for Stage 2 processing
// Preserves duration_tier and searchConfig
// ================================================================

const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

const results = [];

for (const item of items) {
  const data = item.json;

  let video_id = data.id || data.video_id || "";
  let channel_id = data.snippet?.channelId || data.channel_id || "";

  results.push({
    json: {
      // IDs
      video_id: video_id,
      channel_id: channel_id,
      id: data.id,

      // YouTube data
      snippet: data.snippet || {},
      statistics: data.statistics || {},
      contentDetails: data.contentDetails || {},
      channelStatistics: data.channelStatistics || {},

      // Algorithm scores from Stage 1
      features: data.features || {},
      stats: data.stats || {},
      _raw: data._raw || {},

      // Search metadata (for debugging)
      search_label: data.search_label || "Unknown",
      search_intent: data.search_intent || "PROTOCOL",
      search_q: data.search_q || "",
      search_q_full: data.search_q_full || "",
      duration_tier: data.duration_tier || "UNKNOWN",
      _searchConfig: data._searchConfig || {}
    }
  });
}

return results;

// ================================================================
// Code â€” Quality Gate v4.0 (PF Removed)
// 
// CHANGES FROM v3.0:
// - REMOVED: All PF (Problem Framing) references
// - UPDATED: Confidence factors â€” no more STRONG_PROBLEM_FRAMING
// - UPDATED: Quality metrics output â€” PF removed
// 
// Gate logic unchanged:
// 1. Check leak_score minimum (0.45)
// 2. Check AI minimum (1.0)  
// 3. Type-aware DS check (only for true PAIN videos)
// ================================================================

const MIN_LEAK_SCORE = 0.45;  // Universal minimum
const MIN_AI = 1.0;           // Must have authority imbalance

// Type-specific DS thresholds (based on EFFECTIVE type, not search axis)
const DS_THRESHOLDS = {
  PAIN: 0.10,      // Lowered from 0.15 â€” new DS calc is more sensitive
  BUYER: 0.00,     // BUYER videos â€” DS doesn't matter much
  PROTOCOL: 0.00,  // PROTOCOL videos â€” DS irrelevant
  UNKNOWN: 0.00    // Default â€” don't gate on DS
};

const videoData = $input.first().json;
const stats = videoData.stats || {};
const features = videoData.features || {};
const typeDetection = videoData._typeDetection || {};
const scoringInfo = videoData._scoringInfo || {};
const dsAnalysis = videoData._dsAnalysis || {};

const leakScore = stats.leak_score || 0;
const AI = features.AI || 0;
const DS = features.DS || 0;
const ER = features.ER || 0;
const CI = features.CI || 0;

// Use EFFECTIVE type (from content detection), not just search axis
const searchAxis = typeDetection.searchAxis || videoData.search_intent || "PROTOCOL";
const effectiveType = typeDetection.effectiveType || scoringInfo.effectiveType || searchAxis;
const typeSource = typeDetection.typeSource || "SEARCH_AXIS";

// Get appropriate DS threshold based on EFFECTIVE type
const dsThreshold = DS_THRESHOLDS[effectiveType] ?? 0.0;

// Positive ratio from comment analysis
const positiveRatio = dsAnalysis.positiveRatio || 0;

// Build metadata
const gateMetadata = {
  video_id: videoData.id,
  video_title: videoData.snippet?.title || "Unknown",
  leak_score: +leakScore.toFixed(4),
  AI: +AI.toFixed(3),
  DS: +DS.toFixed(3),
  ER: +ER.toFixed(5),
  CI: +CI.toFixed(3),
  stage1_score: stats.stage1_score || 0,
  search_axis: searchAxis,
  effective_type: effectiveType,
  type_source: typeSource,
  positive_ratio: +positiveRatio.toFixed(2),
  ds_threshold_used: dsThreshold
};

// ================================================================
// GATE 1: Primary leak_score threshold
// ================================================================
if (leakScore < MIN_LEAK_SCORE) {
  return [{
    json: {
      _gateResult: "REJECTED",
      _gateReason: `leak_score ${leakScore.toFixed(4)} < ${MIN_LEAK_SCORE} threshold`,
      _gateCode: "LOW_LEAK_SCORE",
      ...gateMetadata
    }
  }];
}

// ================================================================
// GATE 2: Authority Imbalance minimum
// ================================================================
if (AI < MIN_AI) {
  return [{
    json: {
      _gateResult: "REJECTED",
      _gateReason: `AI ${AI.toFixed(3)} < ${MIN_AI} (weak leak signal)`,
      _gateCode: "LOW_AI",
      ...gateMetadata
    }
  }];
}

// ================================================================
// GATE 3: Type-Aware DS Check
// Only apply DS threshold to videos that are ACTUALLY pain-type
// NOT to solution videos found via pain search
// ================================================================
if (effectiveType === "PAIN" && DS < dsThreshold && leakScore < 0.55) {
  return [{
    json: {
      _gateResult: "REJECTED",
      _gateReason: `PAIN-type video: DS ${DS.toFixed(3)} < ${dsThreshold} AND leak_score < 0.55`,
      _gateCode: "LOW_DS_PAIN_TYPE",
      ...gateMetadata
    }
  }];
}

// ================================================================
// PASSED â€” Assign quality tier and confidence factors
// ================================================================
let tier = "GOOD";
if (leakScore >= 0.70) tier = "EXCELLENT";
else if (leakScore >= 0.60) tier = "STRONG";

// Build confidence factors (v4.0 â€” PF removed)
const confidenceFactors = [];

// Traffic leak confirmation (core signal)
if (AI >= 2.0) confidenceFactors.push("EXCEPTIONAL_LEAK");
else if (AI >= 1.5) confidenceFactors.push("CONFIRMED_LEAK");
else if (AI >= 1.2) confidenceFactors.push("STRONG_LEAK");

// Audience signals from comments
if (DS >= 0.25) confidenceFactors.push("DESPERATE_AUDIENCE");
else if (DS >= 0.10) confidenceFactors.push("PAIN_SIGNALS_PRESENT");

if (positiveRatio >= 0.35) confidenceFactors.push("SATISFIED_AUDIENCE");
else if (positiveRatio >= 0.20) confidenceFactors.push("POSITIVE_SENTIMENT");

// Engagement
if (ER >= 0.05) confidenceFactors.push("HIGH_ENGAGEMENT");
else if (ER >= 0.03) confidenceFactors.push("GOOD_ENGAGEMENT");

// Commercial intent
if (CI >= 0.30) confidenceFactors.push("BUYING_INTENT");
else if (CI >= 0.15) confidenceFactors.push("COMPARISON_SHOPPING");

// Special: PAIN search found PROTOCOL video (JACKPOT!)
if (searchAxis === "PAIN" && effectiveType === "PROTOCOL") {
  confidenceFactors.push("PAIN_SEARCH_FOUND_SOLUTION");
}

// ================================================================
// OUTPUT â€” Pass through all video data with gate results
// ================================================================
return [{
  json: {
    ...videoData,
    _gateResult: "PASSED",
    _gateTier: tier,
    _gateConfidence: confidenceFactors.join(", ") || "STANDARD",
    _gateSearchAxis: searchAxis,
    _gateEffectiveType: effectiveType,
    _gateTypeSource: typeSource,
    _qualityMetrics: {
      leak_score: +leakScore.toFixed(4),
      AI: +AI.toFixed(3),
      DS: +DS.toFixed(3),
      ER: +ER.toFixed(5),
      CI: +CI.toFixed(3),
      positive_ratio: +positiveRatio.toFixed(2),
      tier: tier,
      effective_type: effectiveType
      // PF intentionally removed
    }
  }
}];

// ================================================================
// Code â€” Tag Results with Axis â€” v7.0
// 
// Tags each YouTube result with its source query metadata
// Including axis, duration_tier, and full searchConfig for debugging
//
// INPUT: YouTube Search API response
// OUTPUT: Tagged items wrapped for merge
// ================================================================

// Find the query context from upstream nodes
let allQueries = [];
const possibleNodeNames = [
  'Code â€” Build Axis-Specific Search Config',
  'Split Out â€” Searches'
];

for (const nodeName of possibleNodeNames) {
  try {
    allQueries = $(nodeName).all();
    if (allQueries.length > 0) break;
  } catch (e) { }
}

if (allQueries.length === 0) {
  return [{
    json: {
      items: [],
      _error: "Could not find query source node. Check node names."
    }
  }];
}

// Get run index to match query to response
let runIndex;
try {
  runIndex = $runIndex;
} catch (e) {
  try {
    runIndex = $itemIndex;
  } catch (e2) {
    runIndex = 0;
  }
}

// Get the query context for THIS specific search
const queryContext = allQueries[runIndex]?.json || {};

// Get YouTube response
const youtubeResponse = $input.first().json;
const items = youtubeResponse.items || [];

// Handle empty results gracefully
if (items.length === 0) {
  return [{
    json: {
      items: [],
      _query: queryContext.q_full || "",
      _axis: queryContext.axis || "",
      _duration_tier: queryContext.duration_tier || "",
      _searchConfig: queryContext._searchConfig || {},
      _note: "No YouTube results for this query"
    }
  }];
}

// Tag each video with its source query metadata
const taggedItems = items.map(video => ({
  ...video,

  // === Primary Search Metadata ===
  _searchAxis: queryContext.axis || "UNKNOWN",
  _searchLabel: queryContext.label || "",
  _searchQuery: queryContext.q_full || "",
  _duration_tier: queryContext.duration_tier || "UNKNOWN",
  _searchConfig: queryContext._searchConfig || {},

  // === Fields for downstream nodes ===
  search_label: queryContext.label || "",
  search_intent: queryContext.axis || "",
  search_q: queryContext.q || "",
  search_q_full: queryContext.q_full || "",
  duration_tier: queryContext.duration_tier || "",

  // === Run tracking ===
  _runId: queryContext.run_id || "",
  _runIndex: runIndex
}));

// Return wrapped in items array for the Merge node
return [{
  json: {
    items: taggedItems,
    _queryUsed: queryContext.q_full,
    _axisUsed: queryContext.axis,
    _durationTier: queryContext.duration_tier,
    _searchConfig: queryContext._searchConfig,
    _resultCount: taggedItems.length,
    _runIndex: runIndex
  }
}];

// ================================================================
// Code â€” Build Axis-Specific Search Config â€” OPPORTUNITY AXIS v9.0
// 
// Updated for new Opportunity Axis framework:
// - FRUSTRATION: Recent content, relevance-sorted (active problems)
// - TRANSITION: Wider time window (life events are evergreen)
// - DECISION_POINT: Very recent, viewCount-sorted (active buyers)
// ================================================================

const allInputs = $input.all();
const outputs = [];

const now = new Date();
const threeMonthsAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
const sixMonthsAgo = new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
const oneYearAgo = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
const twoYearsAgo = new Date(now.getTime() - 730 * 24 * 60 * 60 * 1000);

const axisConfigs = {
  FRUSTRATION: {
    order: 'relevance',
    publishedAfter: oneYearAgo.toISOString(),
    _rationale: 'Relevance surfaces genuine frustration; 1yr catches ongoing problems'
  },
  TRANSITION: {
    order: 'relevance',
    publishedAfter: twoYearsAgo.toISOString(),
    _rationale: 'Life transitions are evergreen; wider window captures more'
  },
  DECISION_POINT: {
    order: 'viewCount',
    publishedAfter: sixMonthsAgo.toISOString(),
    _rationale: 'ViewCount surfaces popular comparisons; recent = relevant products'
  },
  // Fallback for any legacy axis names
  PAIN: {
    order: 'relevance',
    publishedAfter: oneYearAgo.toISOString(),
    _rationale: 'Legacy PAIN axis â€” mapped to FRUSTRATION behavior'
  },
  PROTOCOL: {
    order: 'viewCount',
    publishedAfter: oneYearAgo.toISOString(),
    _rationale: 'Legacy PROTOCOL axis â€” mapped to TRANSITION behavior'
  },
  BUYER: {
    order: 'viewCount',
    publishedAfter: sixMonthsAgo.toISOString(),
    _rationale: 'Legacy BUYER axis â€” mapped to DECISION_POINT behavior'
  }
};

for (const input of allInputs) {
  const query = input.json;
  const axis = (query.axis || 'FRUSTRATION').toUpperCase();
  const config = axisConfigs[axis] || axisConfigs.FRUSTRATION;

  const commonParams = {
    part: 'snippet',
    q: query.q_full,
    type: 'video',
    maxResults: '50',
    relevanceLanguage: 'en',
    regionCode: 'US',
    order: config.order,
    publishedAfter: config.publishedAfter,
    safeSearch: 'moderate',
    videoEmbeddable: 'true'
  };

  // MEDIUM duration (4-20 min)
  outputs.push({
    json: {
      ...query,
      duration_tier: 'MEDIUM',
      api_params: { ...commonParams, videoDuration: 'medium' },
      _searchConfig: {
        axis: axis,
        duration_tier: 'MEDIUM',
        duration_range: '4-20 min',
        rationale: config._rationale,
        order: config.order,
        publishedAfter: config.publishedAfter.split('T')[0]
      }
    }
  });

  // LONG duration (20+ min)
  outputs.push({
    json: {
      ...query,
      duration_tier: 'LONG',
      api_params: { ...commonParams, videoDuration: 'long' },
      _searchConfig: {
        axis: axis,
        duration_tier: 'LONG',
        duration_range: '20+ min',
        rationale: config._rationale,
        order: config.order,
        publishedAfter: config.publishedAfter.split('T')[0]
      }
    }
  });
}

return outputs;

// ================================================================
// Code â€” Merge Batch Results â€” v7.0
// 
// Combines video stats from multiple batched API calls
// into a single array for downstream processing
// ================================================================

const allInputs = $input.all();
const mergedItems = [];
let combinedSearchMetadata = {};

for (const input of allInputs) {
  const json = input.json;

  // Collect items from videos.list responses
  if (Array.isArray(json.items)) {
    mergedItems.push(...json.items);
  }

  // Merge search metadata maps from all batches
  if (json.search_metadata_map) {
    combinedSearchMetadata = { ...combinedSearchMetadata, ...json.search_metadata_map };
  }
}

return [{
  json: {
    items: mergedItems,
    search_metadata_map: combinedSearchMetadata,
    _mergeStats: {
      total_batches_processed: allInputs.length,
      total_videos_merged: mergedItems.length,
      metadata_keys_preserved: Object.keys(combinedSearchMetadata).length
    }
  }
}];

// ================================================================
// Code â€” Build Master Context (v9.0)
// 
// CANONICAL OUTPUT for all downstream AAS workflows.
// Combines parsed data with Airtable record IDs.
// Updated for new Profiler output structure.
// ================================================================

const parsed = $('Code â€” Clean & Parse Profiler').item.json;
const carousel = $('Config â€” Category Carousel').first().json;
const videoRec = $('Airtable â€” Upsert Videos').item.json;
const channelRec = $('Airtable â€” Upsert Channels').item.json;
const searchRec = $('Airtable â€” Upsert Searches').item.json;
const runRec = $('Airtable â€” Upsert Runs').item.json;
const leakRec = $('Airtable â€” Upsert Traffic Leaks').item.json;

