// Code â€” Parse Opportunity Axis Plan
const raw = $input.all()?.[0]?.json?.output ?? "";
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  return [{ json: { error: "No JSON found", raw } }];
}

try {
  const obj = JSON.parse(match[0]);
  const searches = Array.isArray(obj.searches) ? obj.searches : [];

  // Get macro category
  const macroRaw = $('Config â€” Category Carousel').first().json.target_macro_category || '';
  const run_id = $('Config â€” Category Carousel').first().json.run_id || '';

  // Clean macro phrase
  const STOP = new Set(['and','or','for','to','of','the','a','an','in','on','with']);
  const macroTerms = macroRaw
    .replace(/[&\/]/g, ' ')
    .replace(/[']/g, "'")
    .replace(/[^\w\s'"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(s => s && !STOP.has(s.toLowerCase()))
    .slice(0, 5)
    .join(' ');

  // Build full queries with new axis names
  const allQueries = searches.map((search, idx) => {
    const qRaw = (search.q || '').trim();
    const q_full = [macroTerms, qRaw].filter(Boolean).join(' ').trim();

    // Map new axis names for downstream compatibility
    const axis = (search.axis || 'FRUSTRATION').toUpperCase();

    return {
      axis: axis,
      label: search.label || `Query_${idx + 1}`,
      q: qRaw,
      q_full: q_full,
      q_loose: q_full.replace(/["']/g, ''),
      macro_terms: macroTerms,
      run_id: run_id,
      search_intent: axis
    };
  });

  return [{
    json: {
      all_queries: allQueries,
      macro_terms: macroTerms,
      run_id: run_id,
      _counts: {
        frustration: allQueries.filter(q => q.axis === 'FRUSTRATION').length,
        transition: allQueries.filter(q => q.axis === 'TRANSITION').length,
        decision_point: allQueries.filter(q => q.axis === 'DECISION_POINT').length,
        total: allQueries.length
      }
    }
  }];

} catch (e) {
  return [{ json: { error: "Parse failed: " + e.message, raw } }];
}

