// ================================================================
// HELPERS
// ================================================================
function log10(x) { return Math.log(x) / Math.LN10; }

function daysSince(iso) {
  if (!iso) return 999;
  const t = new Date(iso).getTime();
  if (isNaN(t)) return 999;
  return Math.max(0.1, (Date.now() - t) / (1000 * 60 * 60 * 24));
}

function parseDuration(duration) {
  if (!duration || typeof duration !== 'string') return 0;
  const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!match) return 0;
  return (parseInt(match[1] || '0') * 3600) + 
         (parseInt(match[2] || '0') * 60) + 
         parseInt(match[3] || '0');
}

// ================================================================
// LANGUAGE DETECTION (Post-API filter)
// Returns false for non-English content
// ================================================================
function isLikelyEnglish(title, description, snippet) {
  const defaultLang = snippet?.defaultLanguage || '';
  const audioLang = snippet?.defaultAudioLanguage || '';

  if (defaultLang && !defaultLang.startsWith('en')) return false;
  if (audioLang && !audioLang.startsWith('en')) return false;

  const nonLatinPattern = /[\u0400-\u04FF\u0600-\u06FF\u0E00-\u0E7F\u3040-\u30FF\u3400-\u4DBF\u4E00-\u9FFF\uAC00-\uD7AF\u0590-\u05FF]/;

  if (nonLatinPattern.test(title)) {
    const latinChars = (title.match(/[a-zA-Z]/g) || []).length;
    const totalChars = title.replace(/\s/g, '').length;
    if (latinChars / totalChars < 0.5) return false;
  }

  const turkishSpecific = /[ÄŸÄžÄ±Ä°ÅŸÅžÃ§Ã‡Ã¶Ã–Ã¼Ãœ]/g;
  const turkishMatches = (title.match(turkishSpecific) || []).length;
  if (turkishMatches >= 3) return false;

  return true;
}

