// PROCESS VIDEOS
// ================================================================
const validVideos = [];
const skippedCount = { 
  duration: 0, 
  subs: 0, 
  views: 0, 
  ai: 0, 
  lowValue: 0,
  language: 0 
};

for (const item of items) {
  const json = item.json;
  const tags = [];

  const snippet = json.snippet || {};
  const views = parseInt(json.statistics?.viewCount || 0);
  const likes = parseInt(json.statistics?.likeCount || 0);
  const commentCount = parseInt(json.statistics?.commentCount || 0);
  const subs = parseInt(json.channelStatistics?.subscriberCount || 0);
  const publishedAt = snippet.publishedAt || "";
  const title = (snippet.title || "");
  const titleLower = title.toLowerCase();
  const description = (snippet.description || "").toLowerCase();
  const durationSecs = parseDuration(json.contentDetails?.duration);
  const daysOld = daysSince(publishedAt);

  // Core metric
  const AI = log10(views + 1) - log10(subs + 1);

  // ================================================================
  // HARD FILTERS (order matters for efficiency)
  // ================================================================

  if (!isLikelyEnglish(title, description, snippet)) {
    skippedCount.language++;
    continue;
  }

  if (durationSecs < MIN_DURATION_SECONDS || durationSecs > MAX_DURATION_SECONDS) {
    skippedCount.duration++;
    continue;
  }

  if (subs < MIN_SUBSCRIBER_COUNT || subs > MAX_SUBSCRIBER_COUNT) {
    skippedCount.subs++;
    continue;
  }

  if (views < MIN_VIEW_COUNT) {
    skippedCount.views++;
    continue;
  }

  if (AI < MIN_AUTHORITY_IMBALANCE) {
    skippedCount.ai++;
    continue;
  }

  if (LOW_VALUE_PATTERNS.some(p => titleLower.includes(p))) {
    skippedCount.lowValue++;
    continue;
  }

  // ================================================================
  // OPPORTUNITY SCORING
  // ================================================================

  // Authority Imbalance tiers â€” renamed for opportunity framing
  if (AI >= 2.0) tags.push("EXCEPTIONAL_OPPORTUNITY");
  else if (AI >= 1.5) tags.push("STRONG_OPPORTUNITY");
  else if (AI >= 1.0) tags.push("CONFIRMED_OPPORTUNITY");
  else tags.push("POTENTIAL_OPPORTUNITY");

  // Velocity (views per day)
  const V = views / (daysOld + 1);
  if (V >= 5000) tags.push("VIRAL_MOMENTUM");
  else if (V >= 1000) tags.push("HIGH_MOMENTUM");
  else if (V >= 300) tags.push("MODERATE_MOMENTUM");
  else tags.push("LOW_MOMENTUM");

  // Engagement Rate
  const ER = views > 0 ? (likes + 2 * commentCount) / views : 0;
  if (ER >= 0.05) tags.push("HIGH_ENGAGEMENT");
  else if (ER >= 0.03) tags.push("GOOD_ENGAGEMENT");
  else if (ER >= 0.015) tags.push("MODERATE_ENGAGEMENT");

  // Duration tiers
  let durationBonus = 1.0;
  if (durationSecs >= 1800) {
    durationBonus = 1.3;
    tags.push("DEEP_DIVE_30M+");
  } else if (durationSecs >= 1200) {
    durationBonus = 1.2;
    tags.push("DEEP_DIVE_20M+");
  } else if (durationSecs >= 600) {
    durationBonus = 1.1;
    tags.push("SOLID_LENGTH_10M+");
  }

  // Recency bonus
  let recencyBonus = 1.0;
  if (daysOld <= 30) {
    recencyBonus = 1.15;
    tags.push("FRESH_CONTENT");
  } else if (daysOld <= 90) {
    recencyBonus = 1.05;
    tags.push("RECENT_CONTENT");
  }

  // Preserve search axis
  const searchAxis = json.search_intent || json._searchAxis || "UNKNOWN";
  tags.push(`SEARCH_${searchAxis}`);

  const durationTier = json.duration_tier || "UNKNOWN";
  tags.push(`DURATION_${durationTier}`);

  // ================================================================
  // COMPUTE STAGE 1 SCORE
  // ================================================================
  const AI_norm = Math.min(1, Math.max(0, AI / 2.5));
  const V_norm = Math.min(1, log10(V + 1) / 4);
  const ER_norm = Math.min(1, ER / 0.08);

  const stage1_raw = (0.45 * AI_norm) + (0.25 * V_norm) + (0.30 * ER_norm);
  const stage1_score = stage1_raw * durationBonus * recencyBonus;

  // ================================================================
  // STORE RESULTS
  // ================================================================
  item.json.features = { 
    AI: +AI.toFixed(3), 
    V: +V.toFixed(1), 
    ER: +ER.toFixed(5)
  };

  item.json.stats = {
    stage1_score: +stage1_score.toFixed(4),
    daysOld: +daysOld.toFixed(1),
    durationSecs: durationSecs,
    durationMin: +(durationSecs / 60).toFixed(1),
    tags: tags.join(", ")
  };

  item.json._raw = { views, likes, commentCount, subs };
  item.json.duration_tier = durationTier;
  item.json._searchConfig = json._searchConfig || {};

  validVideos.push(item);
}

// ================================================================
// SORT AND RETURN TOP CANDIDATES
// ================================================================
validVideos.sort((a, b) => b.json.stats.stage1_score - a.json.stats.stage1_score);

const filterStats = {
  total_input: items.length,
  passed_filters: validVideos.length,
  skipped_language: skippedCount.language,
  skipped_duration: skippedCount.duration,
  skipped_subs: skippedCount.subs,
  skipped_views: skippedCount.views,
  skipped_low_ai: skippedCount.ai,
  skipped_low_value: skippedCount.lowValue,
  pass_rate: items.length > 0 
    ? ((validVideos.length / items.length) * 100).toFixed(1) + '%' 
    : '0%'
};

if (validVideos.length === 0) {
  return [{
    json: {
      _error: "No videos passed hard filters",
      _filterStats: filterStats
    }
  }];
}

validVideos[0].json._filterStats = filterStats;

const TOP_CANDIDATES = 25;
return validVideos.slice(0, TOP_CANDIDATES);

// ================================================================
// OPPORTUNITY HUNTER v9.0 â€” Stage 2 (Comment Analysis)
