const videoData = $('Set â€” Current Video Context').item.json;
const commentsResponse = $('API â€” Get Comments').first().json;
const channelResponse = $('API â€” Get Channel Details').first().json;

const commentItems = commentsResponse.items || [];
const channelItem = channelResponse.items?.[0] || {};

const searchAxis = (videoData.search_intent || videoData._searchAxis || "FRUSTRATION").toUpperCase();

// ================================================================
// EXTRACT COMMENTS
