const comments = commentItems.map(item => ({
  text: (item.snippet?.topLevelComment?.snippet?.textOriginal || 
         item.snippet?.topLevelComment?.snippet?.textDisplay || ""),
  likes: item.snippet?.topLevelComment?.snippet?.likeCount || 0,
