// ================================================================
// AFFILIATE READINESS (AR) â€” NEW KEY METRIC
// 
// Detects comments where people are ASKING for recommendations
// vs just saying "thanks" or "great video"
// 
// AR > 0.2 = HIGH affiliate potential
// AR > 0.1 = GOOD affiliate potential  
// AR < 0.05 = LOW affiliate potential (satisfied audience, no asks)
// ================================================================
function computeAR(comments) {
  if (comments.length === 0) return { 
    score: 0, signals: [], askingCount: 0, totalAnalyzed: 0,
    debug: "No comments" 
  };

  // ASKING keywords â€” people seeking recommendations
  const askingKeywords = [
    // Direct product asks
    'what brand', 'which brand', 'what product', 'which product',
    'what do you use', 'what did you use', 'what are you using',
    'which one', 'what kind', 'what type', 'what model',
    'can you recommend', 'do you recommend', 'any recommendations',
    'can you link', 'drop a link', 'link please', 'link in bio',
    'where did you get', 'where can i get', 'where to buy',
    'where do you buy', 'where can i buy', 'how to get',

    // Comparison/decision asks  
    'vs', 'versus', 'or should i', 'which is better',
    'worth it', 'worth the money', 'worth buying',
    'should i buy', 'should i get', 'thinking about buying',
    'is it good', 'does it work', 'did it work',

    // Alternatives/options asks
    'alternative', 'alternatives', 'other options',
    'anything else', 'what else', 'similar to',
    'cheaper option', 'budget option', 'affordable',

    // Specific resource asks
    'what app', 'which app', 'what software', 'what program',
    'what supplement', 'which supplement', 'what dosage',
    'what book', 'which book', 'what course',
    'affiliate link', 'discount code', 'coupon'
  ];

  // NON-ASKING keywords â€” just appreciation (low affiliate value)
  const appREDACTED085CB2 = [
    'thank you so much', 'thanks for sharing', 'really helpful',
    'great video', 'amazing video', 'love this', 'subscribed',
    'needed this', 'exactly what i needed', 'perfect timing'
  ];

  let askingCount = 0;
  let appREDACTEDBD9DCF = 0;
  let signals = [];

  for (const comment of comments) {
    const text = comment.text.toLowerCase();
    let isAsking = false;
    let isAppreciation = false;

    for (const keyword of askingKeywords) {
      if (text.includes(keyword)) {
        if (!isAsking) {
          askingCount++;
          isAsking = true;
        }
        const signal = keyword.toUpperCase().replace(/\s+/g, '_').substring(0, 15);
        if (!signals.includes(signal) && signals.length < 8) {
          signals.push(signal);
        }
      }
    }

    for (const keyword of appREDACTED085CB2) {
      if (text.includes(keyword) && !isAsking) {
        if (!isAppreciation) {
          appREDACTEDBD9DCF++;
          isAppreciation = true;
        }
      }
    }
  }

  const totalAnalyzed = comments.length;
  const askRatio = askingCount / totalAnalyzed;

  // Boost score if many asking comments
  let ar = askRatio;
  if (askingCount >= 5) ar = Math.min(1, ar + 0.08);
  else if (askingCount >= 3) ar = Math.min(1, ar + 0.04);

  return {
    score: Math.min(1, ar),
    signals: signals,
    askingCount: askingCount,
    appREDACTEDBD9DCF: appREDACTEDBD9DCF,
    totalAnalyzed: totalAnalyzed,
    debug: `${totalAnalyzed} comments: ${askingCount} asking, ${appREDACTEDBD9DCF} appreciation`
  };
}

// ================================================================
// DESPERATION SCORE (DS) â€” Unchanged from v8
// ================================================================
function computeDS(comments) {
  if (comments.length === 0) return { 
    score: 0, signals: [], positiveRatio: 0, 
    positiveCount: 0, desperateCount: 0, keywordHits: 0,
    debug: "No comments" 
  };

  const desperationKeywords = [
    'desperate', 'desperation', 'hopeless', 'helpless', 'miserable',
    'suffering', 'unbearable', 'excruciating', 'agony', 'torture',
    'nightmare', 'hell', 'killing me', 'driving me crazy', 'losing my mind',
    'at my wits end', 'wits end', 'end of my rope',
    'nothing works', 'nothing worked', 'tried everything', 'nothing helps',
    'still struggling', 'still suffering', 'getting worse', 'no relief',
    'cant sleep', "can't sleep", 'cant function', "can't function",
    'doesnt work', "doesn't work", 'didnt work', "didn't work",
    'for years', 'for months', 'for weeks', 'chronic', 'constant', 
    'persistent', 'every day', 'every night', 'all the time', 
    'non-stop', 'nonstop', 'ongoing',
    'please help', 'need help', 'any advice', 'any tips', 
    'what should i do', 'does anyone know', 'has anyone', 
    'any suggestions', 'im begging', "i'm begging", 'someone help',
    'ruining my life', 'affecting my', 'destroying my', 'ruined my',
    'cant work', "can't work", 'missed work', 'lost my job',
    'relationship', 'marriage', 'divorce', 'family'
  ];

  const positiveKeywords = [
    'thank you', 'thanks so much', 'thanks for', 'tysm',
    'this worked', 'it worked', 'finally worked', 'actually worked',
    'life saver', 'lifesaver', 'life changer', 'game changer', 'gamechanger',
    'helped me', 'helped so much', 'really helped', 'this helped',
    'fixed my', 'cured my', 'solved my', 'relief',
    'feel better', 'feeling better', 'feel great', 'feeling great',
    'god bless', 'bless you', 'saved my', 'saved me',
    'changed my life', 'wish i found', 'wish i knew', 'years ago',
    'best video', 'amazing video', 'great video', 'excellent',
    'subscribe', 'subscribed', 'new subscriber'
  ];

  let desperateCount = 0;
  let positiveCount = 0;
  let signals = [];
  let totalKeywordHits = 0;

  for (const comment of comments) {
    const text = comment.text.toLowerCase();
    let commentDesperate = false;
    let commentPositive = false;

    for (const keyword of desperationKeywords) {
      if (text.includes(keyword)) {
        totalKeywordHits++;
        if (!commentDesperate) {
          desperateCount++;
          commentDesperate = true;
        }
        const signal = keyword.toUpperCase().replace(/\s+/g, '_').substring(0, 20);
        if (!signals.includes(signal) && signals.length < 10) {
          signals.push(signal);
        }
      }
    }

    for (const keyword of positiveKeywords) {
      if (text.includes(keyword)) {
        if (!commentPositive) {
          positiveCount++;
          commentPositive = true;
        }
      }
    }
  }

  const totalComments = comments.length;
  let ds = desperateCount / totalComments;

  const keywordDensity = totalKeywordHits / Math.max(1, desperateCount);
  if (keywordDensity > 2.0) ds = Math.min(1, ds + 0.12);
  else if (keywordDensity > 1.5) ds = Math.min(1, ds + 0.06);

  if (desperateCount >= 8) ds = Math.min(1, ds + 0.10);
  else if (desperateCount >= 5) ds = Math.min(1, ds + 0.06);
  else if (desperateCount >= 3) ds = Math.min(1, ds + 0.03);

  const positiveRatio = positiveCount / totalComments;

  return {
    score: Math.min(1, ds),
    signals: signals,
    positiveRatio: positiveRatio,
    positiveCount: positiveCount,
    desperateCount: desperateCount,
    keywordHits: totalKeywordHits,
    debug: `${totalComments} comments: ${desperateCount} desperate, ${positiveCount} positive (${(positiveRatio * 100).toFixed(0)}%)`
  };
}

// ================================================================
// COMMERCIAL INTENT (CI) â€” Unchanged
// ================================================================
function computeCI(commentTexts, title, description) {
  const allText = [...commentTexts, title.toLowerCase(), description.toLowerCase()].join(' ');
  let score = 0;
  const signals = [];

  const patterns = [
    { pattern: /(?:where\s+(?:can\s+i|do\s+(?:i|you))\s+(?:buy|get|find|order|purchase))/i, weight: 0.20, signal: "WHERE_TO_BUY" },
    { pattern: /(?:how\s+much|what(?:'s| is) the price|cost)/i, weight: 0.15, signal: "PRICE_INQUIRY" },
    { pattern: /(?:link\s+(?:in|below|please)|drop\s+(?:a\s+)?link)/i, weight: 0.10, signal: "LINK_REQUEST" },
    { pattern: /(?:what\s+(?:brand|model|version|type))/i, weight: 0.15, signal: "BRAND_INQUIRY" },
    { pattern: /(?:vs\.?|versus|compared\s+to|or\s+should\s+i|better\s+than)/i, weight: 0.15, signal: "COMPARISON" },
    { pattern: /(?:alternative\s+to|instead\s+of|similar\s+to)/i, weight: 0.15, signal: "ALTERNATIVE_SEEKING" },
    { pattern: /(?:which\s+(?:one|is\s+better))/i, weight: 0.15, signal: "WHICH_BETTER" },
    { pattern: /(?:amazon|amzn|affiliate)/i, weight: 0.10, signal: "AMAZON_MENTION" },
    { pattern: /(?:recommend|recommendation)/i, weight: 0.12, signal: "RECOMMENDATION" },
    { pattern: /(?:worth\s+(?:it|the\s+(?:money|price|cost)))/i, weight: 0.15, signal: "WORTH_IT" },
    { pattern: /(?:should\s+i\s+(?:buy|get|try))/i, weight: 0.15, signal: "SHOULD_BUY" },
    { pattern: /(?:discount|coupon|code|deal)/i, weight: 0.10, signal: "DISCOUNT_SEEKING" }
  ];

  for (const { pattern, weight, signal } of patterns) {
    if (pattern.test(allText)) {
      score += weight;
      signals.push(signal);
    }
  }

  return { score: Math.min(1, score), signals };
}

// ================================================================
// DETECT VIDEO TYPE FROM CONTENT
// ================================================================
function detectVideoType(title, description, dsResult) {
  const text = `${title} ${description}`.toLowerCase();

  const solutionPatterns = [
    /how\s+(?:to|i)/i,
    /step[\s-]by[\s-]step/i,
    /(?:my\s+)?(?:routine|regimen|protocol|system|method)/i,
    /(?:what\s+(?:worked|helped|fixed))/i,
    /(?:complete|ultimate|full)\s+guide/i,
    /(?:cure|fix|solve|heal|treat|remedy)/i,
    /(?:finally|actually)\s+(?:worked|helped|fixed)/i
  ];

  const frustrationPatterns = [
    /why\s+(?:am\s+i|do\s+i|does|is|can't|won't)/i,
    /(?:symptoms|signs|causes|reasons)\s+(?:of|for|why)/i,
    /what(?:'s|\s+is)\s+(?:wrong|happening|causing)/i,
    /(?:my\s+)?(?:struggle|journey|battle|story)\s+with/i,
    /(?:living|dealing|coping)\s+with/i
  ];

  const decisionPatterns = [
    /(?:\bvs\b|versus|compared)/i,
    /(?:review|unboxing|first\s+(?:look|impressions))/i,
    /(?:best|top\s+\d+|ranking)/i,
    /(?:worth\s+(?:it|the|buying))/i,
    /(?:honest|real)\s+review/i
  ];

  let solutionScore = 0;
  let frustrationScore = 0;
  let decisionScore = 0;

  for (const p of solutionPatterns) if (p.test(text)) solutionScore++;
  for (const p of frustrationPatterns) if (p.test(text)) frustrationScore++;
  for (const p of decisionPatterns) if (p.test(text)) decisionScore++;

  // Comment sentiment can indicate video type
  if (dsResult.positiveRatio >= 0.35) solutionScore += 2;
  else if (dsResult.positiveRatio >= 0.20) solutionScore += 1;

  if (dsResult.score >= 0.25) frustrationScore += 2;
  else if (dsResult.score >= 0.15) frustrationScore += 1;

  const maxScore = Math.max(solutionScore, frustrationScore, decisionScore);

  if (maxScore === 0) return { type: "UNKNOWN", confidence: 0, scores: { solutionScore, frustrationScore, decisionScore } };

  let detectedType;
  if (solutionScore === maxScore) detectedType = "SOLUTION";
  else if (decisionScore === maxScore) detectedType = "DECISION_POINT";
  else detectedType = "FRUSTRATION";

  const secondHighest = [solutionScore, frustrationScore, decisionScore].sort((a, b) => b - a)[1];
  const confidence = maxScore > 0 ? (maxScore - secondHighest) / maxScore : 0;

  return { 
    type: detectedType, 
    confidence: Math.min(1, 0.3 + confidence * 0.7),
    scores: { solutionScore, frustrationScore, decisionScore } 
  };
}

// ================================================================
// COMPUTE FEATURES
