function log10(x) { return Math.log(x) / Math.LN10; }
const AI_norm = Math.min(1, Math.max(0, AI / 2.5));
const V_norm = Math.min(1, log10(V + 1) / 4);
const ER_norm = Math.min(1, ER / 0.08);

// ================================================================
// DETERMINE EFFECTIVE VIDEO TYPE
// ================================================================
let effectiveType = searchAxis;
let typeSource = "SEARCH_AXIS";

// Map old axis names to new
const axisMap = {
  'PAIN': 'FRUSTRATION',
