  else if (videoTypeDetection.confidence >= 0.5) {
    effectiveType = videoTypeDetection.type;
    typeSource = "HIGH_CONFIDENCE_DETECTION";
  }
}

// ================================================================
// CALCULATE OPPORTUNITY SCORE (v9.0 â€” includes AR)
// 
// New weights with Affiliate Readiness:
//   FRUSTRATION:     AI=0.25, V=0.15, ER=0.15, DS=0.20, AR=0.20, CI=0.05
//   DECISION_POINT:  AI=0.25, V=0.15, ER=0.15, DS=0.05, AR=0.15, CI=0.25
//   SOLUTION:        AI=0.30, V=0.15, ER=0.20, DS=0.05, AR=0.15, CI=0.05 + bonus
// ================================================================
let opportunity_score;
let formulaUsed;
let positiveBonus = 0;

if (effectiveType === "FRUSTRATION") {
  opportunity_score = (0.25 * AI_norm) + (0.15 * V_norm) + (0.15 * ER_norm) + (0.20 * DS) + (0.20 * AR) + (0.05 * CI);
  formulaUsed = "FRUSTRATION_WEIGHTED";
} 
else if (effectiveType === "DECISION_POINT") {
  opportunity_score = (0.25 * AI_norm) + (0.15 * V_norm) + (0.15 * ER_norm) + (0.05 * DS) + (0.15 * AR) + (0.25 * CI);
  formulaUsed = "DECISION_POINT_WEIGHTED";
}
else {
  // SOLUTION â€” satisfied audience with asking comments is ideal
  if (dsResult.positiveRatio >= 0.35 && AR >= 0.10) {
    positiveBonus = 0.15; // Satisfied audience PLUS asking for products = gold
  } else if (dsResult.positiveRatio >= 0.35) {
    positiveBonus = 0.10;
  } else if (dsResult.positiveRatio >= 0.20) {
    positiveBonus = 0.05;
  }

  opportunity_score = (0.30 * AI_norm) + (0.15 * V_norm) + (0.20 * ER_norm) + (0.05 * DS) + (0.15 * AR) + (0.05 * CI) + positiveBonus;
  formulaUsed = "SOLUTION_WEIGHTED";
}

// ================================================================
// BUILD TAGS (v9.0 â€” opportunity-focused)
// ================================================================
const tags = [];

// === AUTHORITY IMBALANCE ===
if (AI >= 2.0) tags.push("EXCEPTIONAL_OPPORTUNITY");
else if (AI >= 1.5) tags.push("STRONG_OPPORTUNITY");
else if (AI >= 1.0) tags.push("CONFIRMED_OPPORTUNITY");
else tags.push("WEAK_OPPORTUNITY");

// === VELOCITY ===
if (V >= 1000) tags.push("HIGH_MOMENTUM");
else if (V >= 300) tags.push("MODERATE_MOMENTUM");
else tags.push("LOW_MOMENTUM");

// === ENGAGEMENT ===
if (ER >= 0.05) tags.push("HIGH_ENGAGEMENT");
else if (ER >= 0.02) tags.push("MODERATE_ENGAGEMENT");
else tags.push("LOW_ENGAGEMENT");

// === AFFILIATE READINESS (NEW) ===
if (AR >= 0.25) tags.push("AFFILIATE_GOLDMINE");
else if (AR >= 0.15) tags.push("HIGH_AFFILIATE_POTENTIAL");
else if (AR >= 0.08) tags.push("GOOD_AFFILIATE_POTENTIAL");
else tags.push("LOW_AFFILIATE_SIGNALS");

// === DURATION ===
const durationSecs = videoData.stats?.durationSecs || 0;
if (durationSecs >= 1800) tags.push("DEEP_DIVE_30M+");
else if (durationSecs >= 1200) tags.push("DEEP_DIVE_20M+");
else if (durationSecs >= 600) tags.push("STANDARD_LENGTH");
else if (durationSecs >= 180) tags.push("SHORT_FORM");

// === SEARCH CONTEXT ===
tags.push(`SEARCH_${searchAxis}`);
if (effectiveType !== searchAxis && effectiveType !== axisMap[searchAxis]) {
  tags.push(`DETECTED_${effectiveType}`);
  tags.push("TYPE_MISMATCH_GOLD");
}

// === COMMENT SENTIMENT ===
if (dsResult.positiveRatio >= 0.35) tags.push("SATISFIED_AUDIENCE");
