// ================================================================
// DENVER TIME HELPERS
// ================================================================
function getDenverTime() {
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Denver',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hour12: false
  });
  const parts = fmt.formatToParts(now);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const d = parts.find(p => p.type === 'day').value;
  const h = parseInt(parts.find(p => p.type === 'hour').value);
  return {
    dayKey: `${y}-${m}-${d}`,
    hour: h,
    isAM: h < 12
  };
}

// ================================================================
// STATE MANAGEMENT â€” TWO-LEVEL ROUND ROBIN
// ================================================================
const data = $getWorkflowStaticData('global');
const denver = getDenverTime();
const runType = denver.isAM ? 'AM' : 'PM';

// Initialize state if needed
if (typeof data.outletIndex !== 'number') data.outletIndex = 0;
if (typeof data.categoryIndexByOutlet !== 'object' || data.categoryIndexByOutlet === null) {
  data.categoryIndexByOutlet = {};
}
if (typeof data.lastDayKey !== 'string') data.lastDayKey = '';
if (typeof data.lastRunType !== 'string') data.lastRunType = '';

// ================================================================
// DUPLICATE RUN PREVENTION
// ================================================================
const firstRun = data.lastDayKey === '';
const sameDay = data.lastDayKey === denver.dayKey;
const alreadyRanThisSlot = sameDay && data.lastRunType === runType;

if (alreadyRanThisSlot) {
  return {
    json: {
      _skip: true,
      _reason: `Already ran ${runType} slot today`,
      day_key: denver.dayKey,
      run_type: runType
    }
  };
}

// ================================================================
// TWO-LEVEL ROUND ROBIN LOGIC
// 
// Level 1: Rotate through brand outlets (ensures each outlet gets hit regularly)
// Level 2: Rotate through categories within that outlet
// 
// Result: With 6 outlets and 14 runs/week, each outlet gets ~2-3 hits/week
// ================================================================

// LEVEL 1: Pick the next brand outlet (round robin)
const currentOutlet = BRAND_OUTLETS[data.outletIndex % BRAND_OUTLETS.length];

// LEVEL 2: Pick the next category within that outlet (round robin)
const outletKey = currentOutlet.outlet_key;
const categories = currentOutlet.categories;

// Initialize category index for this outlet if needed
if (typeof data.categoryIndexByOutlet[outletKey] !== 'number') {
  data.categoryIndexByOutlet[outletKey] = 0;
}

const categoryIndex = data.categoryIndexByOutlet[outletKey] % categories.length;
const selectedCategory = categories[categoryIndex];

// ================================================================
// ADVANCE BOTH POINTERS (except on first run)
// ================================================================
if (!firstRun) {
  // Advance category index for this outlet
  data.categoryIndexByOutlet[outletKey] = (categoryIndex + 1) % categories.length;

  // Advance outlet index
  data.outletIndex = (data.outletIndex + 1) % BRAND_OUTLETS.length;
}

// Update timestamp state
data.lastDayKey = denver.dayKey;
data.lastRunType = runType;

// ================================================================
// BUILD RUN ID
// ================================================================
const randomSuffix = Math.random().toString(36).substring(2, 8);
const run_id = `RUN-${denver.dayKey}-${runType}-${outletKey}-${randomSuffix}`;

// ================================================================
// COMPUTE ROTATION STATS
// ================================================================
const totalCategories = BRAND_OUTLETS.reduce((sum, o) => sum + o.categories.length, 0);
const outletCategoryCount = categories.length;

// How many runs until this specific category repeats?
// = outletCategoryCount Ã— number of outlets
const categoryRepeatCycle = outletCategoryCount * BRAND_OUTLETS.length;

